export default function selectTelegramDocument({body}) {
 if(!body||typeof body!=='object'||Array.isArray(body)||!body.message||typeof body.message!=='object')throw new Error('A Telegram message event is required.');
 const document=body.message.document;
 return {hasDocument:!!document&&typeof document==='object'&&!Array.isArray(document),body};
}

