export default function prepareTelegramDocument({body,folderId}) {
 const doc=body.message.document;
 if(!doc||typeof doc.file_id!=='string'||!doc.file_id)throw new Error('A Telegram document file ID is required.');
 if(typeof folderId!=='string'||!folderId.trim()||folderId.startsWith('YOUR_'))throw new Error('Set the Google Drive folder ID.');
 return {fileId:doc.file_id,fileRequest:{file_id:doc.file_id},fileName:typeof doc.file_name==='string'?doc.file_name:'',mimeType:typeof doc.mime_type==='string'&&doc.mime_type?doc.mime_type:'application/octet-stream',folderId};
}

