export default async function verifyTelegramAudioBot({botToken,providerBotId,providerIsBot},context) {
 if(typeof botToken!=='string'||!/^\d+:[A-Za-z0-9_-]+$/.test(botToken))throw new Error('Select the Telegram audio Bot Token Variable.');
 if(!Number.isSafeInteger(providerBotId)||providerIsBot!==true)throw new Error('The Telegram connection did not identify a bot.');
 try {
  const response=await context.fetch('https://api.telegram.org/bot'+botToken+'/getMe',{method:'GET'});
  if(!response.ok)throw new Error('Unconfirmed identity.');
  const reply=await response.json();
  if(reply?.ok!==true||reply.result?.is_bot!==true||reply.result.id!==providerBotId)throw new Error('Unmatched bot.');
  return {verified:true,botId:providerBotId};
 } catch {throw new Error('The audio Bot Token must identify the same bot as the selected Telegram connection.');}
}

