import {Buffer} from 'node:buffer';
export default async function downloadTelegramDocument({botToken,verified,reply,statusCode,fileId,fileName,mimeType,folderId},context) {
 if(verified!==true||typeof botToken!=='string'||!/^\d+:[A-Za-z0-9_-]+$/.test(botToken))throw new Error('Verify the Telegram bot token before downloading.');
 const file=reply?.result,path=file?.file_path;
 if(statusCode!==200||reply?.ok!==true||file?.file_id!==fileId||typeof path!=='string'||!path||path.startsWith('/')||path.split('/').some(x=>!x||x==='.'||x==='..')||/[?#\\\x00-\x20]/.test(path))throw new Error('Telegram did not confirm a valid downloadable document.');
 const name=fileName||path.split('/').at(-1);if(!name)throw new Error('Telegram did not provide a document name.');
 try{const response=await context.fetch('https://api.telegram.org/file/bot'+botToken+'/'+path.split('/').map(encodeURIComponent).join('/'),{method:'GET'});if(!response.ok)throw new Error('Download failed.');const bytes=new Uint8Array(await response.arrayBuffer());if(typeof file.file_size==='number'&&(!Number.isSafeInteger(file.file_size)||file.file_size<0||file.file_size!==bytes.length))throw new Error('Document size mismatch.');return {name,mimeType,parents:[folderId],contentBase64:bytes.length?Buffer.from(bytes).toString('base64'):null,size:bytes.length,fileId};}catch{throw new Error('Telegram document download failed; no partial content was uploaded.');}
}

