export default function confirmTelegramDriveFile({id,name,mimeType,parents,sizeBytes,expectedName,folderId,fileId,bytes}) {
 if(typeof id!=='string'||!id||name!==expectedName||!Array.isArray(parents)||!parents.includes(folderId))throw new Error('Drive did not confirm the created file; it may already exist, inspect Drive before replaying.');
 if(sizeBytes!==null&&sizeBytes!==bytes)throw new Error('Drive returned an unexpected file size; inspect Drive before replaying.');
 return {result:{status:"uploaded",file:{id,name,mimeType,parents,sizeBytes},sourceFileId:fileId,bytes}};
}
